.slider input:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: var(--focus-outline-offset, 2px); }
.marks { position: relative; height: 1rem; margin-top: calc(var(--space-2) * -1); color: var(--text-muted); font-size: var(--text-xs); }
.marks span { position: absolute; transform: translateX(-50%); white-space: nowrap; }
.marks span:first-child { transform: none; }
.periodRow { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-3); }
.savings { color: var(--success); font-size: var(--text-sm); font-variant-numeric: tabular-nums; }
.card { display: grid; align-content: start; gap: var(--space-2); min-width: 0; padding: var(--space-5); border: 1px solid var(--border-strong); border-radius: var(--radius-panel); background: var(--surface-raised); }
.planLabel { margin: 0; color: var(--text-secondary); font-size: var(--text-xs); }
.planName { margin: 0; font-family: var(--font-display); font-size: var(--text-3xl); font-weight: 500; letter-spacing: var(--tracking-display); line-height: var(--leading-display); min-height: 1.2em; }
.reason { margin: 0; color: var(--text-secondary); font-size: var(--text-sm); }
.amount { display: flex; align-items: baseline; gap: var(--space-2); margin: var(--space-2) 0 0; font-family: var(--font-display); font-size: var(--text-4xl); letter-spacing: var(--tracking-display); line-height: var(--leading-display); font-variant-numeric: tabular-nums; }
.amount small { color: var(--text-secondary); font-family: var(--font-body); font-size: var(--text-sm); letter-spacing: 0; }
.note { margin: 0; color: var(--text-secondary); font-size: var(--text-xs); }
.features { display: grid; gap: var(--space-1); margin: var(--space-2) 0; padding: var(--space-3) 0 0; border-top: 1px solid var(--border-subtle); list-style: none; font-size: var(--text-sm); }
