.status { margin: 0; min-height: 1.25rem; color: var(--text-secondary); font-size: var(--text-xs); }
.status[data-tone="error"] { color: var(--danger); }
.contact { display: grid; gap: var(--space-2); padding: var(--space-4) 0; }
.contact p { margin: 0; color: var(--text-secondary); font-size: var(--text-sm); }
.breakdown h4 { margin: 0 0 var(--space-2); font-size: var(--text-sm); font-weight: 500; }
.breakdown dl { display: grid; gap: var(--space-1); margin: 0; }
.breakdown dl div { display: flex; justify-content: space-between; gap: var(--space-4); padding: var(--space-2) 0; border-bottom: 1px solid var(--border-subtle); font-size: var(--text-sm); font-variant-numeric: tabular-nums; }
.breakdown dt { color: var(--text-secondary); }
.breakdown dd { margin: 0; text-align: right; }
.totalRow { border-bottom: 0 !important; font-size: var(--text-base) !important; }
.totalRow b { font-family: var(--font-display); font-size: var(--text-xl); font-weight: 500; }
.scale { height: .25rem; margin-top: var(--space-3); border-radius: var(--radius-pill); background: var(--surface-muted); overflow: hidden; }
