@container (max-width: 560px) { .root { padding: var(--space-4); } .amount { font-size: var(--text-3xl); } .planName { font-size: var(--text-2xl); } .breakdown dl div { flex-direction: column; gap: var(--space-1); } .breakdown dd { text-align: left; } }
.root[data-reduced] .scale span { transition: none; }
